<body>
  <a href="#main-content" class="skip-link">Skip to main content</a>

  <div class="viz-menu" aria-label="Visualization menu">
    <button class="viz-menu-toggle" onclick="document.querySelector('.viz-menu-dropdown').classList.toggle('open')">Menu</button>
    <div class="viz-menu-dropdown">
      <button onclick="downloadImage()">Download PNG</button>
      <button onclick="window.print()">Print</button>
    </div>
  </div>

  <main id="main-content">
    <section class="header">
      <div class="eyebrow">ACADEMIC CONFERENCE POSTER · NEUROSCIENCE SYMPOSIUM</div>
      <h1>Mapping Neural Circuit Architecture</h1>
      <div class="subtitle">Large-scale connectomics reveals new principles of brain circuit organization through a step-change in mapping scale and precision.</div>
      <div class="citation">Nature (2024) · DOI: 10.1038/s41586-024-07487-w</div>
    </section>

    <section class="metrics">
      <div class="metric"><div class="label">Neurons Mapped</div><div class="value">~125k</div><div class="ctx">Total reconstructed neurons</div></div>
      <div class="metric"><div class="label">Synaptic Connections</div><div class="value">~54M</div><div class="ctx">Identified synapses catalogued</div></div>
      <div class="metric"><div class="label">Circuit Motifs</div><div class="value">37</div><div class="ctx">Novel recurrent connectivity motifs</div></div>
      <div class="metric"><div class="label">Auto Classification Accuracy</div><div class="value">94.2%</div><div class="ctx">CNN-based classifier performance</div></div>
    </section>

    <section class="grid">
      <section class="card">
        <h2>Background & Motivation</h2>
        <p>Neural computation depends on precise circuit wiring, yet whole-circuit maps at sufficient resolution and scale remained elusive. This 2024 Nature study combines nanometer-scale EM with automated reconstruction to bridge structure and function in cortical microcircuitry.</p>
      </section>

      <section class="card">
        <h2>Methodology & Technical Approach</h2>
        <div class="pipeline">
          <div class="step"><div class="n">01</div><div class="t">EM Imaging</div><div class="d">4×4×30 nm serial-section electron microscopy</div></div>
          <div class="step"><div class="n">02</div><div class="t">Segmentation</div><div class="d">Deep-learning reconstruction + expert proofreading</div></div>
          <div class="step"><div class="n">03</div><div class="t">Synapse Detection</div><div class="d">CNN classifier for automated identification</div></div>
          <div class="step"><div class="n">04</div><div class="t">Graph Analysis</div><div class="d">Motif detection, clustering, hub analysis</div></div>
          <div class="step"><div class="n">05</div><div class="t">Validation</div><div class="d">Calcium imaging + optogenetic perturbation</div></div>
        </div>
      </section>
    </section>

    <section class="card findings" style="margin-top:18px;">
      <h2>Key Findings</h2>
      <div class="finding-grid">
        <div class="finding"><div class="k">37 Distinct Motifs</div><div class="v">Recurring modules suggest a finite circuit vocabulary for cortical computation.</div></div>
        <div class="finding"><div class="k">Hub Dominance</div><div class="v">~3.5% of neurons account for ~28% of synaptic output, indicating strong influence concentration.</div></div>
        <div class="finding"><div class="k">Layer Rules</div><div class="v">Feedforward dominance from L2/3→L4; layer 5 shows recurrent enrichment (4.7:1).</div></div>
        <div class="finding"><div class="k">Cell-Type Specificity</div><div class="v">Inhibitory interneurons display 6.2× higher wiring specificity than excitatory neurons.</div></div>
      </div>
      <div class="chart-wrap">
        <canvas id="findingsChart" role="img" aria-label="Quantitative key findings chart"></canvas>
      </div>
    </section>

    <section class="card" style="margin-top:18px;">
      <h2>Implications & Future Directions</h2>
      <p>These results support a modular architecture of cortical computation and identify high-impact hub nodes as potential intervention targets. The open connectomic dataset and analysis toolkit provide a foundation for cross-region and cross-species scaling, advancing toward whole-brain wiring diagrams with integrated functional priors.</p>
      <div class="footer">Prepared for academic conference dissemination · Audience: Neuroscientists, systems neuroscience, computational connectomics.</div>
    </section>
  </main>

  <script>
    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') {
          console.error('Chart.js not loaded');
          return null;
        }
        try {
          if (this.charts.has(canvasId)) {
            this.charts.get(canvasId).destroy();
            this.charts.delete(canvasId);
          }
          var ctx = document.getElementById(canvasId);
          if (!ctx) {
            console.error('Canvas element not found: ' + canvasId);
            return null;
          }
          if (ctx.chart) {
            ctx.chart.destroy();
            delete ctx.chart;
          }
          ctx.setAttribute('role', 'img');
          if (!ctx.getAttribute('aria-label')) {
            ctx.setAttribute('aria-label', 'Chart visualization');
          }
          var chart = new Chart(ctx, config);
          this.charts.set(canvasId, chart);
          return chart;
        } catch (error) {
          console.error('Chart initialization failed for ' + canvasId + ':', error);
          return null;
        }
      }
    };

    function initCharts() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      var styles = getComputedStyle(document.documentElement);
      ChartManager.safeInit('findingsChart', {
        type: 'bar',
        data: {
          labels: ['Motifs', 'Hub Output Share', 'L5 Recurrent Ratio', 'Inhibitory Specificity', 'Classifier Accuracy'],
          datasets: [{
            label: 'Quantitative Findings',
            data: [37, 28, 4.7, 6.2, 94.2],
            backgroundColor: [
              'rgba(49,208,255,0.8)',
              'rgba(49,240,194,0.8)',
              'rgba(255,200,87,0.85)',
              'rgba(100,227,139,0.8)',
              'rgba(49,208,255,0.95)'
            ],
            borderColor: styles.getPropertyValue('--border').trim(),
            borderWidth: 1.2
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: { tooltip: { enabled: true }, legend: { display: false } },
          scales: {
            x: { ticks: { color: styles.getPropertyValue('--text-secondary').trim(), font: { size: 12 } }, grid: { color: 'rgba(185,198,234,0.12)' } },
            y: { ticks: { color: styles.getPropertyValue('--text-secondary').trim() }, grid: { color: 'rgba(185,198,234,0.12)' } }
          }
        }
      });
    }

    function downloadImage() {
      var node = document.getElementById('main-content');
      if (!window.htmlToImage || !node) return;
      htmlToImage.toPng(node, { pixelRatio: 2, backgroundColor: getComputedStyle(document.documentElement).getPropertyValue('--bg').trim() })
        .then(function(dataUrl) {
          var link = document.createElement('a');
          link.download = 'neural-circuit-poster.png';
          link.href = dataUrl;
          link.click();
        })
        .catch(function(err) { console.error('download failed', err); });
    }

    window.addEventListener('load', initCharts);
  </script>
